ArrayList<Circle> circles = new ArrayList<Circle>();
let colour = true;

function setup() {
  createCanvas(500, 500);
  for (i = width; i > 0; i -= width/20) {
    let circle = new Circle();
    circle.size = i;
    circle.colour = colour;
    colour = !colour;
    circles.add(circle);
  }
	background(230);
}

function draw() {
  noStroke();
  for (i = circles.size() - 1; i >= 0; i--) {
    var circle = circles.get(i);
    let circleShow = circles.get(circles.size() - 1 - i);
    if (circle.colour) {
      fill(20, 50, 50);
    } else {
      fill(230);
    }
    ellipse(width/2, height/2 + 50, circleShow.size, circleShow.size);
    circle.size += 2;
    if (circle.size >= width) {
      let newCircle = new Circle();
      newCircle.size = 1;
      newCircle.colour = colour;
      circles.add(newCircle);
      colour = !colour;
      circles.remove(circle);
    }
  }
  strokeWeight(450);
  stroke(230);
  noFill();
  triangle(width/2, -350, -350, height + 150, width +375, height + 150);
	noise();
}

function noise() {
  noStroke();
  strokeWeight(1);
  for (i = 0; i < width - 1; i += 5) {
    for (j = 0; j < height - 1; j += 5) {
      fill(random(0, 255), random(30, 50));
      rect(random(i - 5, i), random(j - 5, j), 1, 1);
    }
  }
  for (i = 0; i < 5; i++) {
    fill(random(0, 255), 255);
    rect(random(0, width), random(0, height), 2, 2);
  }
}

class Circle {
  size;
  colour;
}

